/**
 * Fantasy RPG mode game module for local_stackmathgame.
 *
 * Implements the visual RPG layer: mana bar, fairy counter, scene narrative
 * bubble, and teleport-style next-scene navigation. Scene types drive mana
 * gain (boss > miniboss > challenge > instruction).
 *
 * Based on alquiz-fantasy-bg-ver3.js
 * (c) 2022 Malte Neugebauer, Hochschule Bochum (MIT Licence).
 * Adapted for the local_stackmathgame subplugin AMD module contract.
 *
 * @module     stackmathgamemode_rpg/game
 * @copyright  2026 Ralf Erlebach
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(['local_stackmathgame/game_core'], function(GameCore) {

    'use strict';

    /**
     * Return the element that shows the stage counter, creating it on first use.
     *
     * Created lazily: a quiz whose pages hold one question each never has a group, and an empty
     * element in every HUD would be markup nobody asked for.
     *
     * @param {Element} parent The container to attach it to.
     * @returns {Element|null} The element, or null when there is no container.
     */
    function stageElement(parent) {
        if (!parent) {
            return null;
        }
        var existing = parent.querySelector('.smg-rpg-stage');
        if (existing) {
            return existing;
        }
        var element = document.createElement('div');
        element.className = 'smg-rpg-stage small text-muted d-none';
        // Announced politely: the counter changes as a side effect of answering, and an assertive
        // region would interrupt what the screen reader is saying about the answer itself.
        element.setAttribute('aria-live', 'polite');
        parent.appendChild(element);
        return element;
    }

    /** Mana gained per scene type on first solve. */
    var MANA_GAIN = {
        boss:        30,
        miniboss:    15,
        challenge:   10,
        reward:      10,
        transition:   5,
        instruction:  0,
        outro:        5
    };

    /** Starting mana value (mirrors alquiz-fantasy default). */
    var MANA_MAX = 100;
    var MANA_START = 20;

    /**
     * Build a slot-keyed map from the questionmap array.
     *
     * @param {Array} questionmap Array of questionmap rows from get_quiz_config.
     * @returns {Object} Map of slotnumber (string) to configjson object.
     */
    function buildSlotMap(questionmap) {
        var map = {};
        (questionmap || []).forEach(function(row) {
            var cfg = null;
            try {
                cfg = row.configjson ? JSON.parse(row.configjson) : null;
            } catch (e) {
                cfg = null;
            }
            map[String(row.slotnumber)] = cfg || GameCore.defaultConfig();
        });
        return map;
    }

    /**
     * Inject Fantasy RPG CSS into the document head.
     *
     * Styles the HUD bar (mana / fairies), narrative bubble, and
     * teleport-style next button.
     *
     * @returns {void}
     */
    function injectStyles() {
        if (document.getElementById('smg-rpg-styles')) {
            return;
        }
        var style = document.createElement('style');
        style.id = 'smg-rpg-styles';
        style.textContent = [
            /* HUD container */
            '.smg-rpg-hud {',
            '  background: linear-gradient(135deg, #1a1a2e, #16213e);',
            '}',
            '.smg-rpg-stage {',
            '  position: relative;',
            '  min-height: 160px;',
            '  margin-bottom: .5rem;',
            '  border-radius: .5rem;',
            '  background-size: cover;',
            '  background-position: center;',
            '}',
            '.smg-rpg-sprite {',
            '  position: absolute;',
            '  bottom: 0;',
            '  max-height: 120px;',
            '}',
            '.smg-rpg-sprite-player { left: 8%; }',
            '.smg-rpg-sprite-enemy { right: 8%; }',
            '.smg-rpg-hud-spacer {',
            '  background: linear-gradient(135deg, #1a1a2e, #16213e);',
            '  color: #e0e0ff;',
            '  padding: .75em 1em;',
            '  border-radius: .5em;',
            '  margin-bottom: 1em;',
            '}',
            '.smg-rpg-hud-inner {',
            '  display: flex;',
            '  align-items: center;',
            '  gap: .75em;',
            '  flex-wrap: wrap;',
            '}',
            /* Mana bar */
            '.smg-rpg-manabar-outer {',
            '  flex: 1;',
            '  background: #333;',
            '  border-radius: 4px;',
            '  height: 12px;',
            '  min-width: 80px;',
            '}',
            '.smg-rpg-manabar-inner {',
            '  height: 100%;',
            '  background: linear-gradient(90deg, #4a90e2, #9b59b6);',
            '  border-radius: 4px;',
            '  transition: width .6s ease;',
            '}',
            /* Narrative bubble */
            '.smg-rpg-narrative {',
            '  display: none;',
            '  position: relative;',
            '  background: #fcefdc;',
            '  padding: 1.125em 1.5em;',
            '  font-size: 1.1em;',
            '  border-radius: 1rem;',
            '  box-shadow: 0 .125rem .5rem rgba(0,0,0,.3);',
            '  margin-bottom: 1em;',
            '}',
            '.smg-rpg-narrative::before {',
            '  content: "";',
            '  position: absolute;',
            '  top: 100%;',
            '  left: 1.5em;',
            '  border: .75rem solid transparent;',
            '  border-bottom: none;',
            '  border-top-color: #fcefdc;',
            '  filter: drop-shadow(0 .0625rem .0625rem rgba(0,0,0,.1));',
            '}',
            /* Teleport next-scene button */
            '.smg-rpg-next {',
            '  display: none;',
            '  margin-top: .5em;',
            '  background: linear-gradient(90deg, #4a90e2, #9b59b6);',
            '  color: #fff;',
            '  border: none;',
            '  padding: .5em 1.25em;',
            '  border-radius: .4em;',
            '  cursor: pointer;',
            '  font-size: 1em;',
            '}',
            '.smg-rpg-next:hover {',
            '  opacity: .85;',
            '}',
        ].join('\n');
        document.head.appendChild(style);
    }

    /**
     * Rebuild the HUD state from the profile the server keeps.
     *
     * Recomputed from the set of solved slots rather than accumulated, so a reload, a second tab
     * or a duplicate submission all arrive at the same number - there is nothing to double-count.
     *
     * @param {Object} gameState The state handed to init().
     * @param {Object} slotMap The slot configuration by slot number.
     * @returns {{mana: number, fairies: number}} The derived HUD state.
     */
    function computeScore(gameState, slotMap) {
        var score = {mana: MANA_START, fairies: 0};
        var profile = gameState.profile || {};
        // The web service exports the progress as a JSON string, not as a structure - Moodle's
        // external API cannot describe an object with arbitrary slot numbers as keys.
        var progress = {};
        try {
            progress = JSON.parse(profile.progressjson || '{}') || {};
        } catch (e) {
            progress = {};
        }
        var slots = progress.slots || {};

        Object.keys(slots).forEach(function(slot) {
            if (!slots[slot] || !slots[slot].solved) {
                return;
            }
            var cfg = slotMap[String(slot)] || {};
            var type = (cfg.scene && cfg.scene.type) ? cfg.scene.type : 'challenge';
            var gain = MANA_GAIN[type] !== undefined ? MANA_GAIN[type] : 10;
            score.mana = Math.min(MANA_MAX, score.mana + gain);
            score.fairies++;
        });

        return score;
    }

    /**
     * Read the cached HUD state for this campaign.
     *
     * @param {string} key The campaign-scoped storage key.
     * @returns {Object|null} The cached state, or null when there is none or it is unreadable.
     */
    function readCachedScore(key) {
        try {
            var stored = sessionStorage.getItem(key);
            if (!stored) {
                return null;
            }
            var parsed = JSON.parse(stored);
            if (parsed && typeof parsed.mana === 'number') {
                return {mana: parsed.mana, fairies: parsed.fairies || 0};
            }
        } catch (e) {
            // A malformed or unavailable cache simply means recomputing from the profile, which
            // is the source of truth anyway.
            return null;
        }
        return null;
    }

    /**
     * Cache the HUD state for this campaign.
     *
     * @param {string} key The campaign-scoped storage key.
     * @param {Object} score The state to cache.
     * @returns {void}
     */
    function writeCachedScore(key, score) {
        try {
            sessionStorage.setItem(key, JSON.stringify(score));
        } catch (e) {
            // Private browsing or a full quota: the HUD still works, it just recomputes from the
            // profile on the next page load.
            return;
        }
    }

    /**
     * Build the scene stage from the design's own assets.
     *
     * The RPG package manifest declares bg_forest, player_idle and enemy_idle, and until now
     * nothing requested any of them - the mode drew CSS gradients instead. That made the asset
     * chain untestable: a resolver returning the wrong URL looked exactly like one returning the
     * right URL.
     *
     * Every asset is optional. A design that omits one simply has no sprite there, rather than a
     * broken image.
     *
     * @param {Object} gameState The state handed to init().
     * @param {Element} anchor The element to insert the stage before.
     * @returns {Element|null} The stage element, or null when the design supplies no assets.
     */
    function buildStage(gameState, anchor) {
        var background = GameCore.assetUrl(gameState, 'bg_forest');
        var player = GameCore.assetUrl(gameState, 'player_idle');
        var enemy = GameCore.assetUrl(gameState, 'enemy_idle');
        if (!background && !player && !enemy) {
            return null;
        }

        var stage = document.createElement('div');
        stage.className = 'smg-rpg-stage';
        if (background) {
            stage.style.backgroundImage = 'url("' + background + '")';
        }
        [['player', player], ['enemy', enemy]].forEach(function(pair) {
            if (!pair[1]) {
                return;
            }
            var sprite = document.createElement('img');
            sprite.className = 'smg-rpg-sprite smg-rpg-sprite-' + pair[0];
            sprite.src = pair[1];
            // Decorative: the mathematical content is the question, not the scenery, and a
            // screen reader announcing "player idle" on every scene is noise.
            sprite.alt = '';
            sprite.setAttribute('role', 'presentation');
            stage.appendChild(sprite);
        });

        if (anchor && anchor.parentNode) {
            anchor.parentNode.insertBefore(stage, anchor);
        }
        return stage;
    }

    /**
     * Build the HUD DOM element and insert it before the first question.
     *
     * @returns {{hud: Element, manaBar: Element, manaText: Element, fairyCount: Element}}
     */
    function buildHUD() {
        var hud = document.createElement('div');
        hud.className = 'smg-rpg-hud';
        hud.innerHTML = [
            '<div class="smg-rpg-hud-inner">',
            '  <span class="smg-rpg-label">🧙 Mana</span>',
            '  <div class="smg-rpg-manabar-outer">',
            '    <div class="smg-rpg-manabar-inner" style="width:' + MANA_START + '%"></div>',
            '  </div>',
            '  <span class="smg-rpg-mana-text">' + MANA_START + '</span>',
            '  <span class="smg-rpg-fairies ms-3">🧚 <span class="smg-rpg-fairy-count">0</span></span>',
            '</div>',
        ].join('');
        var first = document.querySelector('.que');
        if (first && first.parentNode) {
            first.parentNode.insertBefore(hud, first);
        }
        return {
            hud: hud,
            manaBar:    hud.querySelector('.smg-rpg-manabar-inner'),
            manaText:   hud.querySelector('.smg-rpg-mana-text'),
            fairyCount: hud.querySelector('.smg-rpg-fairy-count')
        };
    }

    /**
     * Build the narrative bubble and insert it after the HUD.
     *
     * @param {Element} hud The HUD element.
     * @returns {Element} The narrative bubble element.
     */
    function buildNarrativeBubble(hud) {
        var bubble = document.createElement('div');
        bubble.className = 'smg-rpg-narrative';
        if (hud && hud.parentNode) {
            hud.parentNode.insertBefore(bubble, hud.nextSibling);
        }
        return bubble;
    }

    /**
     * Build the next-scene button and insert it after the narrative bubble.
     *
     * @param {Element} bubble The narrative bubble element.
     * @returns {Element} The next-scene anchor element.
     */
    function buildNextButton(bubble) {
        var btn = document.createElement('a');
        btn.className = 'smg-rpg-next';
        btn.textContent = '⚡ Nächste Szene';
        if (bubble && bubble.parentNode) {
            bubble.parentNode.insertBefore(btn, bubble.nextSibling);
        }
        return btn;
    }

    /**
     * Update the HUD mana bar and fairy counter.
     *
     * @param {{manaBar: Element, manaText: Element, fairyCount: Element}} hudParts HUD elements.
     * @param {number} mana    Current mana value (0–100).
     * @param {number} fairies Current fairy count.
     * @returns {void}
     */
    function updateHUD(hudParts, mana, fairies) {
        var safeMana = Math.max(0, Math.min(100, mana));
        if (hudParts.manaBar) {
            hudParts.manaBar.style.width = safeMana + '%';
        }
        if (hudParts.manaText) {
            hudParts.manaText.textContent = String(safeMana);
        }
        if (hudParts.fairyCount) {
            hudParts.fairyCount.textContent = String(fairies);
        }
    }

    // ── Public interface ───────────────────────────────────────────────────

    /**
     * Initialise the Fantasy RPG mode.
     *
     * @param {Object} gameState Bootstrap data from game_engine.
     * @param {Object} gameState.config PHP config.
     * @param {Object} gameState.design Design record.
     * @param {Object} gameState.profile Player profile.
     * @param {Array}  gameState.questionmap Array of questionmap rows.
     * @param {Array}  gameState.narrative Initial narrative lines.
     * @param {Object} gameState.assets Design assets by manifest key.
     * @param {string} gameState.assetBaseUrl Shared fallback directory; do not append to it.
     * @returns {{onAnswer: Function}} Game module interface.
     */
    function init(gameState) {
        injectStyles();

        var slotMap = buildSlotMap(gameState.questionmap);
        var hudParts = buildHUD();
        buildStage(gameState, hudParts.hud);
        var bubble = buildNarrativeBubble(hudParts.hud);
        var nextBtn = buildNextButton(bubble);

        // The HUD is derived from the server's own record of which scenes are solved, not
        // accumulated locally. That makes it survive a reload, keeps it in step with the rewards
        // the server actually granted, and makes double submissions harmless by construction:
        // recomputing from a set of solved slots cannot double-count.
        var score = computeScore(gameState, slotMap);

        // Session storage is a cache for the moment between a submit and the next page load,
        // not the source of truth. The key carries the campaign so two RPG quizzes open in one
        // browser session cannot bleed into each other - the old key was a bare
        // "smg_rpg_score" shared by every quiz.
        var cacheKey = 'smg_rpg_score:' + (
            (gameState.config && (gameState.config.labelid || gameState.config.quizid)) || 'unknown'
        );
        var cached = readCachedScore(cacheKey);
        if (cached && cached.fairies > score.fairies) {
            // Only ever ahead of the server, never behind: the cache exists to bridge the gap
            // before the profile is re-read, so a stale cache must not undo real progress.
            score = cached;
        }

        updateHUD(hudParts, score.mana, score.fairies);

        // Show intro narrative.
        var currentSlot = parseInt(
            (document.querySelector('.que') || {}).getAttribute
                ? (document.querySelector('.que').getAttribute('data-smg-slot') || '0')
                : '0',
            10
        );
        if (currentSlot) {
            var introCfg = slotMap[String(currentSlot)];
            var introText = introCfg && introCfg.narrative && introCfg.narrative.intro
                ? introCfg.narrative.intro
                : '';
            if (introText) {
                bubble.innerHTML = introText;
                bubble.style.display = 'block';
            }
        }

        return {
            /**
             * React to a submit_answer response.
             *
             * Updates mana/fairy score, shows narrative bubble, and configures
             * the next-scene navigation link.
             *
             * @param {Object} response The submit_answer web service response.
             * @returns {void}
             */
            onAnswer: function(response) {
                var slot = response.slot || currentSlot;
                var solved = !!response.cannext;
                var cfg = slotMap[String(slot)] || GameCore.defaultConfig();
                var sceneType = cfg.scene && cfg.scene.type ? cfg.scene.type : 'challenge';

                // Deliberately firstsolve, not cannext: cannext means "you may move on" and stays
                // true for every later correct answer to a solved scene, so awarding on it let
                // a player farm mana and fairies by resubmitting - while the server correctly
                // granted no score or XP at all. The comment here used to claim this was
                // prevented; nothing checked it.
                if (response.firstsolve) {
                    var gain = MANA_GAIN[sceneType] !== undefined ? MANA_GAIN[sceneType] : 10;
                    score.mana = Math.min(MANA_MAX, score.mana + gain);
                    score.fairies++;
                    writeCachedScore(cacheKey, score);
                }

                updateHUD(hudParts, score.mana, score.fairies);

                // Show narrative text.
                var narrativeKey = solved ? 'success' : 'fail';
                var narrativeText = cfg.narrative && cfg.narrative[narrativeKey]
                    ? cfg.narrative[narrativeKey]
                    : '';
                if (narrativeText) {
                    bubble.innerHTML = GameCore.escapeHtml(narrativeText);
                    bubble.style.display = 'block';
                } else {
                    bubble.style.display = 'none';
                }

                // Render the navigation the server resolved. This mode no longer reads
                // cfg.branching: the resolver is canonical, and re-deciding here is what left
                // linear scenes - the default - without any way forward.
                var decision = GameCore.navigationFrom(response);
                GameCore.applyNavigation(nextBtn, decision);
                // Where the player stands inside a quest or a set of alternatives. Rendered by the
                // shared helper so all three modes agree on when a group is worth mentioning.
                GameCore.applyGroupProgress(
                    stageElement(hudParts.hud),
                    decision,
                    M.util.get_string('stageprogress', 'local_stackmathgame')
                );
            }
        };
    }

    return {init: init};
});
